-- Disposable-test fixture only: existing Production-equivalent invoker audit.
create or replace function public.invoice_number_key(p_number text)
returns text language sql immutable as $$
    select nullif(regexp_replace(trim(coalesce(p_number, '')), '\.0+$', ''), '')
$$;

create table public.invoice_change_log (
    id bigint generated by default as identity primary key,
    changed_at timestamptz not null default timezone('utc', now()),
    action text not null check (action in ('create', 'update', 'renumber',
        'payment_status_change', 'delete', 'credit_note', 'cancellation', 'replace')),
    invoice_row_id bigint,
    invoice_number text,
    old_invoice_number text,
    new_invoice_number text,
    project_name text,
    old_values jsonb,
    new_values jsonb,
    changed_by text,
    source text,
    reason text
);

create or replace function public.invoice_audit_trigger()
returns trigger
language plpgsql
as $$
declare
    v_headers json;
    v_actor   text;
    v_source  text;
    v_reason  text;
    v_action  text;
begin
    begin
        v_headers := nullif(current_setting('request.headers', true), '')::json;
    exception when others then
        v_headers := null;
    end;
    v_actor  := coalesce(nullif(current_setting('caddycheck.actor', true), ''),  v_headers ->> 'x-crm-actor',  current_user);
    v_source := coalesce(nullif(current_setting('caddycheck.source', true), ''), v_headers ->> 'x-crm-source', 'db');
    v_reason := nullif(current_setting('caddycheck.reason', true), '');

    if tg_op = 'INSERT' then
        v_action := case when coalesce(new.payment_amount, 0) < 0 then 'credit_note' else 'create' end;
        insert into public.invoice_change_log
            (action, invoice_row_id, invoice_number, project_name, new_values, changed_by, source, reason)
        values
            (v_action, new.id, new.invoice_number, new.project_name, to_jsonb(new), v_actor, v_source, v_reason);
        return new;

    elsif tg_op = 'DELETE' then
        insert into public.invoice_change_log
            (action, invoice_row_id, invoice_number, project_name, old_values, changed_by, source, reason)
        values
            ('delete', old.id, old.invoice_number, old.project_name, to_jsonb(old), v_actor, v_source, v_reason);
        return old;

    else  -- UPDATE
        if to_jsonb(old) = to_jsonb(new) then
            return new;  -- upsert re-writing an identical row: nothing changed, nothing to log
        end if;
        if public.invoice_number_key(old.invoice_number) is distinct from public.invoice_number_key(new.invoice_number) then
            v_action := 'renumber';
        elsif lower(trim(coalesce(old.paid, ''))) is distinct from lower(trim(coalesce(new.paid, ''))) then
            v_action := case when lower(trim(coalesce(new.paid, ''))) = 'cancelled'
                             then 'cancellation' else 'payment_status_change' end;
        else
            v_action := 'update';
        end if;
        insert into public.invoice_change_log
            (action, invoice_row_id, invoice_number, old_invoice_number, new_invoice_number, project_name,
             old_values, new_values, changed_by, source, reason)
        values
            (v_action, new.id, coalesce(new.invoice_number, old.invoice_number),
             old.invoice_number, new.invoice_number, new.project_name,
             to_jsonb(old), to_jsonb(new), v_actor, v_source, v_reason);
        return new;
    end if;
end;
$$;

create trigger invoices_audit
    after insert or update or delete on public.invoices
    for each row execute function public.invoice_audit_trigger();
